import React, { Component } from 'react';
import Nav from 'react-bootstrap/Nav';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { solid } from '@fortawesome/fontawesome-svg-core/import.macro';

const MONACO_VS = 'https://cdn.jsdelivr.net/npm/monaco-editor@0.52.0/min/vs';
const LSP_WORKER = './zeek-lsp/zeek-lsp-worker.js';

function monacoCompletionKind(lspKind) {
    const map = {
        1: 17, 2: 1, 3: 2, 4: 3, 5: 4, 6: 5, 7: 6, 8: 7, 9: 8,
        10: 9, 12: 11, 13: 12, 14: 17, 16: 14, 17: 20, 18: 21,
    };
    return map[lspKind] || 0;
}

function filenameFromUri(uri) {
    return uri.path.split('/').pop();
}

function zeekMonarchTokenizer() {
    return {
        keywords: [
            'module', 'export', 'global', 'local', 'const', 'option', 'type',
            'redef', 'function', 'hook', 'event', 'return', 'if', 'else', 'for',
            'while', 'break', 'next', 'print', 'in', 'of', 'table', 'set', 'vector',
            'record', 'enum', 'add', 'delete', 'when', 'timeout', 'schedule',
            'true', 'false', 'T', 'F',
        ],
        tokenizer: {
            root: [
                [/##!.*$/, 'comment.zeekygen'],
                [/##<.*$/, 'comment.zeekygen'],
                [/##.*$/, 'comment.zeekygen'],
                [/#.*$/, 'comment'],
                [/"([^"\\]|\\.)*"/, 'string'],
                [/\b(0x[\da-fA-F]+|\d+(\.\d+)?([eE][+-]?\d+)?)\b/, 'number'],
                [/\b[A-Z][A-Z_0-9]*\b/, 'type.identifier'],
                [/@(load|load-sigs|load-plugin|unload|prefixes|if|ifdef|ifndef|else|endif|priority|deprecated)\b/, 'keyword.directive'],
                [/\b(module|export|global|local|const|option|type|redef|function|hook|event|return|if|else|for|while|break|next|print|in|of|table|set|vector|record|enum|add|delete|when|timeout|schedule)\b/, 'keyword'],
                [/\b(T|F|true|false)\b/, 'keyword.constant'],
                [/[{}()[\],;]/, 'delimiter'],
                [/[a-zA-Z_]\w*/, 'identifier'],
            ],
        },
    };
}

class ZeekEditor extends Component {
    constructor(props) {
        super(props);
        this.editorDiv = React.createRef();
        this.monacoEditor = null;
        this.models = {};        // filename -> Monaco model
        this.worker = null;
        this.pendingId = 0;
        this.pending = new Map();
        this._suppressChange = false;
    }

    // --- Worker RPC ---

    setupWorker() {
        this.worker = new Worker(LSP_WORKER, { type: 'module' });
        this.worker.onmessage = ({ data }) => {
            const p = this.pending.get(data.id);
            if (p) { this.pending.delete(data.id); p(data.result); }
        };
        this.worker.onerror = err => console.warn('LSP worker error:', err.message);
    }

    callWorker(msg) {
        return new Promise(resolve => {
            const id = ++this.pendingId;
            this.pending.set(id, resolve);
            this.worker.postMessage({ ...msg, id });
        });
    }

    // --- Monaco setup ---

    setupEditor() {
        if (!this.editorDiv.current) return;  // component unmounted before Monaco loaded
        const monaco = window.monaco;

        if (!monaco.languages.getLanguages().find(l => l.id === 'zeek')) {
            monaco.languages.register({ id: 'zeek', extensions: ['.zeek', '.bro'] });
            monaco.languages.setMonarchTokensProvider('zeek', zeekMonarchTokenizer());
            this.registerProviders(monaco);
        }

        this.monacoEditor = monaco.editor.create(this.editorDiv.current, {
            language: 'zeek',
            theme: 'vs-dark',
            fontSize: 14,
            minimap: { enabled: false },
            automaticLayout: true,
            tabSize: 4,
        });

        this.monacoEditor.onDidChangeModelContent(() => {
            if (this._suppressChange) return;
            const model = this.monacoEditor.getModel();
            if (!model) return;
            const filename = filenameFromUri(model.uri);
            const content = model.getValue();
            this.props.onCodeChanged(filename, content);
            this.callWorker({ type: 'noop', uri: model.uri.toString(), content }).catch(() => {});
        });

        this.syncModels(this.props.code.sources, this.props.code.current);
        this.updateMarkers(this.props.errors);
    }

    registerProviders(monaco) {
        monaco.languages.registerCompletionItemProvider('zeek', {
            triggerCharacters: [':', '$', '@'],
            provideCompletionItems: async (model, position) => {
                const content = model.getValue();
                const line = position.lineNumber - 1;
                const col = position.column - 1;
                try {
                    const result = await this.callWorker({
                        type: 'complete', uri: model.uri.toString(), content, line, col,
                    });
                    if (!result) return { suggestions: [] };
                    const items = Array.isArray(result) ? result
                        : (Array.isArray(result.items) ? result.items : []);
                    const word = model.getWordUntilPosition(position);
                    const range = {
                        startLineNumber: position.lineNumber,
                        endLineNumber: position.lineNumber,
                        startColumn: word.startColumn,
                        endColumn: word.endColumn,
                    };
                    return {
                        suggestions: items.map(item => ({
                            label: item.label,
                            kind: monacoCompletionKind(item.kind),
                            detail: item.detail || '',
                            documentation: item.documentation
                                ? (typeof item.documentation === 'string'
                                    ? item.documentation
                                    : item.documentation.value || '')
                                : '',
                            insertText: item.insertText || item.label,
                            insertTextRules: item.insertTextFormat === 2
                                ? monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet
                                : undefined,
                            range,
                        })),
                    };
                } catch (e) {
                    return { suggestions: [] };
                }
            },
        });

        monaco.languages.registerHoverProvider('zeek', {
            provideHover: async (model, position) => {
                const content = model.getValue();
                const line = position.lineNumber - 1;
                const col = position.column - 1;
                try {
                    const result = await this.callWorker({
                        type: 'hover', uri: model.uri.toString(), content, line, col,
                    });
                    if (!result) return null;
                    const arr = Array.isArray(result.contents) ? result.contents : [];
                    return {
                        contents: arr.map(item => ({
                            value: typeof item === 'string' ? item : (item.value || ''),
                        })),
                        range: result.range ? {
                            startLineNumber: result.range.start.line + 1,
                            startColumn: result.range.start.character + 1,
                            endLineNumber: result.range.end.line + 1,
                            endColumn: result.range.end.character + 1,
                        } : undefined,
                    };
                } catch (e) {
                    return null;
                }
            },
        });
    }

    syncModels(sources, current) {
        const monaco = window.monaco;
        if (!monaco || !this.monacoEditor) return;

        const newNames = new Set(sources.map(s => s.name));

        // Dispose removed models
        for (const name of Object.keys(this.models)) {
            if (!newNames.has(name)) {
                this.models[name].dispose();
                delete this.models[name];
            }
        }

        // Create or update models
        for (const src of sources) {
            if (!this.models[src.name]) {
                const uri = monaco.Uri.parse(`file:///workspace/${src.name}`);
                this.models[src.name] = monaco.editor.createModel(src.content, 'zeek', uri);
            } else if (this.models[src.name].getValue() !== src.content) {
                this._suppressChange = true;
                this.models[src.name].setValue(src.content);
                this._suppressChange = false;
            }
        }

        // Switch to the current file
        if (current && this.models[current]) {
            const active = this.monacoEditor.getModel();
            if (!active || filenameFromUri(active.uri) !== current) {
                this.monacoEditor.setModel(this.models[current]);
            }
        }
    }

    updateMarkers(errors) {
        const monaco = window.monaco;
        if (!monaco) return;
        for (const [filename, model] of Object.entries(this.models)) {
            const fileErrors = errors[filename] || [];
            const markers = fileErrors.map(e => ({
                startLineNumber: e.row + 1,
                startColumn: e.column + 1,
                endLineNumber: e.row + 1,
                endColumn: 1000,
                message: e.text,
                severity: e.type === 'error'
                    ? monaco.MarkerSeverity.Error
                    : monaco.MarkerSeverity.Warning,
            }));
            monaco.editor.setModelMarkers(model, 'zeek', markers);
        }
    }

    // --- Lifecycle ---

    componentDidMount() {
        this.setupWorker();
        window.require.config({ paths: { vs: MONACO_VS } });
        window.require(['vs/editor/editor.main'], () => this.setupEditor());
    }

    componentDidUpdate(prevProps) {
        if (!this.monacoEditor) return;
        if (this.props.code !== prevProps.code) {
            this.syncModels(this.props.code.sources, this.props.code.current);
        }
        if (this.props.errors !== prevProps.errors) {
            this.updateMarkers(this.props.errors);
        }
    }

    componentWillUnmount() {
        if (this.monacoEditor) this.monacoEditor.dispose();
        Object.values(this.models).forEach(m => m.dispose());
        if (this.worker) this.worker.terminate();
    }

    // --- Tab interaction ---

    handleSelect(key) {
        if (key === 'ADD') {
            this.props.onAddFile();
        } else if (this.props.code.current === key && key !== 'main.zeek') {
            const new_name = prompt(`Rename ${key} to`, key);
            if (new_name && new_name !== '' && new_name !== key)
                this.props.onRenameFile(new_name);
        } else if (this.props.code.current !== key) {
            this.props.onSelectFile(key);
        }
    }

    render() {
        const { code } = this.props;
        const addButton = <span><FontAwesomeIcon icon={solid('plus')} /> Add File</span>;
        return (
            <div>
                <Nav variant="tabs" activeKey={code.current}
                     onSelect={k => this.handleSelect(k)}>
                    {code.sources.map(s => (
                        <Nav.Item key={s.name}>
                            <Nav.Link eventKey={s.name}>{s.name}</Nav.Link>
                        </Nav.Item>
                    ))}
                    <Nav.Item>
                        <Nav.Link eventKey="ADD">{addButton}</Nav.Link>
                    </Nav.Item>
                </Nav>
                <div ref={this.editorDiv} style={{ height: '500px', width: '100%' }} />
            </div>
        );
    }
}

export default ZeekEditor;
