function parseZeekLog(text) {
    const lines = text.split(/\r?\n/);
    let sep = '\t';
    let fields = null;
    let types = null;

    for (const line of lines) {
        if (!line.startsWith('#')) break;
        // Header lines use either a space (#separator \x09) or a tab (#fields\t...)
        const wsIdx = line.search(/[ \t]/);
        if (wsIdx === -1) continue;
        const k = line.slice(1, wsIdx);
        const v = line.slice(wsIdx + 1);
        if (k === 'separator') {
            sep = v.replace(/\\x09/g, '\t').replace(/\\t/g, '\t');
        } else if (k === 'fields') {
            fields = v.split(sep);
        } else if (k === 'types') {
            types = v.split(sep);
        }
    }

    if (!fields) return text;

    const rows = [];
    for (const line of lines) {
        if (line === '' || line.startsWith('#')) continue;
        rows.push(line.split(sep));
    }

    return { header: fields, types, rows };
}

// Returns { stdout, stderr, files: { [name]: string|{header,types,rows} } }
// createZeekModule is a global injected by <script src="zeek.js">
export async function runZeek(sources, pcapBuffer) {
    return new Promise((resolve, reject) => {
        const stdout = [];
        const stderr = [];
        // eslint-disable-next-line no-undef
        createZeekModule({
            noInitialRun: true,
            print: function(t) { stdout.push(t); },
            printErr: function(t) { stderr.push(t); },
            preRun: [function(m) {
                m.FS.mkdir('/work');
                m.FS.chdir('/work');
                if (pcapBuffer)
                    m.FS.writeFile('/work/input.pcap', new Uint8Array(pcapBuffer));
                for (const src of sources)
                    m.FS.writeFile('/work/' + src.name, src.content);
            }],
            onRuntimeInitialized: function() {
                const args = [];
                if (pcapBuffer) args.push('-r', '/work/input.pcap', '--no-checksums');
                for (const src of sources) args.push('/work/' + src.name);
                this.callMain(args);
            },
            onExit: function() {
                const files = {};
                try {
                    for (const f of this.FS.readdir('/work')) {
                        if (f.endsWith('.log')) {
                            const raw = this.FS.readFile('/work/' + f, { encoding: 'utf8' });
                            files[f] = parseZeekLog(raw);
                        }
                    }
                } catch (_) {}
                resolve({ stdout: stdout.join('\n'), stderr: stderr.join('\n'), files });
            }
        }).catch(reject);
    });
}
